cases.bad:
// offscreen: sends debug broadcast
chrome.runtime.sendMessage({ type: '_OFFSCREEN_DEBUG', data });
// content script: listens but never receives
chrome.runtime.onMessage.addListener((msg) => {
  if (msg.type === '_OFFSCREEN_DEBUG') { /* never fires */ }
});

cases.good:
// offscreen: send to background only
chrome.runtime.sendMessage({ type: 'OFFSCREEN_DEBUG_LOG', data });
// background: relay to chrome.storage.local for content script to poll
chrome.runtime.onMessage.addListener((msg) => {
  if (msg.type === 'OFFSCREEN_DEBUG_LOG') {
    debugBuf.push(msg.data);
    chrome.storage.local.set({ __offscreenDebugLog: debugBuf.slice(-100) });
  }
});
// content script: poll chrome.storage.local
setInterval(() => {
  chrome.storage.local.get('__offscreenDebugLog', (result) => {
    if (result.__offscreenDebugLog) { /* process logs */ }
  });
}, 2000);
